        const big = new Uint8Array(1500);
        await expect(client.sendDatagram(big)).rejects.toThrow(/exceeds max/);

        await server.close();
    }, 10000);

    it("rapid datagram sends eventually apply backpressure", async () => {
        const server = createServer({
            port: 14461,
