            new WebTransport(`https://127.0.0.1:${port}`, {
                serverCertificateHashes: [{ algorithm: "sha-384" as "sha-256", value: new Uint8Array(32) }],
            })
        ).toThrow(/only supports algorithm "sha-256"/);
    });

